import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u03")
C = "A2-B1"

L(1, "Gaan + infinitivo", "Ik ga morgen boodschappen doen.",
  ["Falar de planos próximos com gaan + infinitivo"],
  vocab=[V("v-van-plan","van plan zijn","tencionar|ter planos de","expression",note="Ik ben van plan om te verhuizen."), V("v-volgend-jaar","volgend jaar","no próximo ano","expression"),
         V("v-straks","straks","daqui a pouco","adverb"), V("v-binnenkort","binnenkort","em breve","adverb")],
  ex=[("Ik ga morgen boodschappen doen.","Amanhã vou fazer compras."),("We gaan volgend jaar verhuizen.","Vamos mudar de casa no próximo ano."),("Straks ga ik koken.","Daqui a pouco vou cozinhar."),("Binnenkort ga ik op vakantie.","Em breve vou de férias.")],
  gram=[G("g-gaan-inf","Gaan + infinitivo","Como o nosso «ir + infinitivo»: **gaan** conjugado na 2.ª posição e o **infinitivo no fim**: *Ik **ga** morgen **koken**.* É a forma mais comum de falar de planos.",
    [("Wat ga je dit weekend doen?","O que vais fazer este fim de semana?"),("Het gaat regenen.","Vai chover.")],
    "A estrutura é igual à portuguesa, mas o infinitivo vai para o fim da frase.")],
  review=["v-gaan","v-morgen","v-weekend","v-verhuizen"],
  cefr=C, exs=[
    MA([("straks","daqui a pouco"),("binnenkort","em breve"),("volgend jaar","no próximo ano"),("van plan zijn","tencionar")], "Futuro próximo.", ["v-straks","v-binnenkort","v-volgend-jaar","v-van-plan"]),
    WO("Amanhã vou fazer compras.", ["Ik","ga","morgen","boodschappen","doen"], "Infinitivo no fim.", ["v-gaan"], alt=["Morgen ga ik boodschappen doen"]),
    TR("pt-nl","O que vais fazer este fim de semana?", ["Wat ga je dit weekend doen","Wat ga jij dit weekend doen"], "gaan + doen no fim.", ["v-gaan"]),
    TR("nl-pt","Het gaat regenen.", ["Vai chover"], "gaan + infinitivo.", ["v-gaan"]),
    FE(["Ik","ga","koken","straks."], 2, "straks", "O infinitivo vai para o fim: Ik ga straks koken.", ["v-straks"]),
    FB("We ___ volgend jaar verhuizen.", ["gaan"], "wij → gaan.", ["v-volgend-jaar"], choices=["gaan","gaat","ga"], tr="Vamos mudar de casa no próximo ano."),
    TR("pt-nl","Em breve vou de férias.", ["Binnenkort ga ik op vakantie","Ik ga binnenkort op vakantie"], "Inversão se começar com binnenkort.", ["v-binnenkort"]),
    LI("Straks ga ik koken.", ["Straks ga ik koken"], "Daqui a pouco vou cozinhar.", "Inversão.", ["v-straks"]),
    DL([("Femke","Wat ga je vanavond doen?","O que vais fazer hoje à noite?"),("Rita","")], ["*Ik ga een film kijken.","Ik heb een film gekeken.|Isso é passado.","Ik ga een film.|Falta o verbo no fim."], "gaan + infinitivo.", ["v-gaan"]),
    MC("«Tenciono aprender a nadar.»", ["*Ik ben van plan om te leren zwemmen.","Ik heb plan zwemmen.|Não é a expressão.","Ik plan zwemmen.|Pouco natural."], "van plan zijn om te + inf.", ["v-van-plan"]),
  ], diff=3, mins=6)

L(2, "Zullen: promessas e previsões", "Ik zal je helpen. Dat zal wel goed komen.",
  ["Usar zullen para promessas, previsões e propostas"],
  vocab=[V("v-zullen","zullen","(futuro) -ei / irá","verb",note="ik zal, jij zult/zal, hij zal, wij zullen"), V("v-beloven","beloven","prometer","verb",note="beloofd"),
         V("v-zeker","zeker","certamente|com certeza","adverb"), V("v-zullen-we","zullen we…?","e se…? (proposta)","expression",note="Zullen we gaan? = Vamos?")],
  ex=[("Ik zal je helpen.","Eu ajudo-te. / Hei de ajudar-te."),("Ik beloof het.","Prometo."),("Het zal zeker lukken.","Vai certamente correr bem."),("Zullen we een kopje koffie drinken?","Vamos tomar um café?")],
  gram=[G("g-zullen","Zullen","**zullen** + infinitivo no fim exprime **promessa** (*Ik zal het doen*), **previsão** mais formal (*Het zal morgen regenen*) e, com *we*, uma **proposta**: *Zullen we gaan?* (Vamos?). No dia a dia, para planos, prefere-se *gaan* ou o presente.",
    [("Ik zal je morgen bellen.","Ligo-te amanhã (prometo)."),("Zullen we morgen afspreken?","Combinamos para amanhã?")],
    "«Zullen we…?» funciona como o nosso «Vamos…?» ou «E se…?».")],
  review=["v-helpen","v-zou","v-bellen"],
  cefr=C, exs=[
    MA([("zullen","futuro / irá"),("beloven","prometer"),("zeker","com certeza"),("zullen we…?","vamos…?")], "Zullen.", ["v-zullen","v-beloven","v-zeker","v-zullen-we"]),
    CJ("zullen","ik","Ik ___ je morgen bellen.", ["zal"], "ik zal.", ["v-zullen"], tense="futuro"),
    CJ("zullen","wij","___ we naar het park gaan?", ["Zullen"], "Proposta: Zullen we…?", ["v-zullen-we"], tense="futuro"),
    TR("pt-nl","Vamos tomar um café?", ["Zullen we [een kopje|een] koffie drinken","Zullen we koffie gaan drinken"], "Zullen we + infinitivo.", ["v-zullen-we"]),
    TR("nl-pt","Ik beloof het.", ["Prometo","Eu prometo","Prometo-te"], "beloven.", ["v-beloven"]),
    MC("Qual é uma promessa?", ["*Ik zal het morgen doen.","Ik deed het morgen.|Mistura passado e futuro.","Ik heb het morgen gedaan.|Perfectum com «morgen» não faz sentido aqui."], "zal + infinitivo.", ["v-zullen"]),
    FE(["Ik","zal","je","helpt."], 3, "helpen", "Depois de zal vem o infinitivo: helpen.", ["v-zullen"]),
    LI("Het zal zeker lukken.", ["Het zal zeker lukken"], "Vai certamente correr bem.", "zeker.", ["v-zeker"]),
    DL([("Daan","Ik heb zo veel werk vandaag.","Tenho tanto trabalho hoje."),("Mia","")], ["*Ik zal je helpen!","Ik heb je geholpen!|Passado — ainda não ajudou.","Zullen we helpen jij?|Ordem errada."], "Promessa com zal.", ["v-zullen"]),
    WO("Combinamos para amanhã?", ["Zullen","we","morgen","afspreken?"], "Zullen we + … + infinitivo.", ["v-zullen-we"]),
  ], diff=3, mins=6)

L(3, "O presente com sentido de futuro", "Morgen werk ik thuis. Volgende week ben ik vrij.",
  ["Usar o presente com uma indicação de tempo para falar do futuro"],
  vocab=[V("v-volgende-week","volgende week","na próxima semana","expression"), V("v-over-twee-weken","over twee weken","daqui a duas semanas","expression"),
         V("v-vanmiddag","vanmiddag","esta tarde","adverb"), V("v-dit-weekend","dit weekend","este fim de semana","expression")],
  ex=[("Morgen werk ik thuis.","Amanhã trabalho em casa."),("Volgende week ben ik vrij.","Na próxima semana estou de folga."),("Over twee weken vertrek ik.","Parto daqui a duas semanas."),("Vanmiddag heb ik een afspraak.","Esta tarde tenho uma marcação.")],
  gram=[G("g-presente-futuro","Presente = futuro","Em neerlandês, se a frase tiver uma indicação de tempo futuro (*morgen, volgende week, over twee weken*), o **presente** basta: *Morgen werk ik thuis.* **over** + período = daqui a: *over een uur* (daqui a uma hora).",
    [("Ik bel je over een uur.","Ligo-te daqui a uma hora."),("Dit weekend blijf ik thuis.","Este fim de semana fico em casa.")],
    "Tal como em português («amanhã trabalho em casa»). Atenção: «over» com tempo = daqui a, não «sobre».")],
  review=["v-morgen","v-thuiswerken","v-vrij","v-afspraak"],
  cefr=C, exs=[
    MA([("volgende week","na próxima semana"),("over twee weken","daqui a duas semanas"),("vanmiddag","esta tarde"),("dit weekend","este fim de semana")], "Expressões de futuro.", ["v-volgende-week","v-over-twee-weken","v-vanmiddag","v-dit-weekend"]),
    TR("pt-nl","Amanhã trabalho em casa.", ["Morgen werk ik thuis","Ik werk morgen thuis"], "Presente + morgen.", []),
    TR("pt-nl","Ligo-te daqui a uma hora.", ["Ik bel je over een uur","Over een uur bel ik je"], "over een uur.", ["v-over-twee-weken"]),
    TR("nl-pt","Volgende week ben ik vrij.", ["Na próxima semana estou de folga","Para a semana estou livre","Na próxima semana estou livre"], "Presente com sentido futuro.", ["v-volgende-week"]),
    MC("«Daqui a duas semanas» diz-se…", ["*over twee weken","twee weken geleden|Isso é «há duas semanas».","sinds twee weken|Isso é «desde há duas semanas»."], "over + período.", ["v-over-twee-weken"]),
    WO("Este fim de semana fico em casa.", ["Dit","weekend","blijf","ik","thuis"], "Inversão.", ["v-dit-weekend"]),
    FE(["Volgende","week","ik","ben","vrij."], 2, "ben", "Depois de «Volgende week» vem o verbo: Volgende week ben ik vrij.", ["v-volgende-week"]),
    FB("Ik vertrek ___ drie dagen.", ["over"], "over = daqui a.", ["v-over-twee-weken"], choices=["over","geleden","sinds"], tr="Parto daqui a três dias."),
    LI("Vanmiddag heb ik een afspraak bij de tandarts.", ["Vanmiddag heb ik een afspraak bij de tandarts"], "Esta tarde tenho consulta no dentista.", "vanmiddag.", ["v-vanmiddag"]),
    AR("week","a semana","de", "De week.", ["v-volgende-week"]),
  ], diff=3, mins=6)

L(4, "Desejos e sonhos", "Ik wil graag… Ik hoop dat… Later wil ik…",
  ["Falar de desejos e planos a longo prazo"],
  vocab=[V("v-hopen","hopen","esperar (ter esperança)","verb"), V("v-droom","droom","sonho","noun","de","dromen"),
         V("v-ooit-fut","ooit (futuro)","um dia","adverb",note="Ik wil ooit naar Japan.")],
  ex=[("Ik hoop dat het morgen mooi weer is.","Espero que amanhã esteja bom tempo."),("Mijn droom is een eigen bedrijf.","O meu sonho é ter uma empresa própria."),("Later wil ik in het buitenland wonen.","No futuro quero viver no estrangeiro."),("Ik wil ooit naar Japan.","Um dia quero ir ao Japão.")],
  gram=[G("g-hopen-dat","Ik hoop dat … (verbo no fim)","Depois de **dat** começa uma oração subordinada: o verbo conjugado vai para o **fim**: *Ik hoop dat het mooi weer **is**.* Também: *Ik hoop **te** slagen* (espero passar).",
    [("Ik hoop dat je komt.","Espero que venhas."),("Ik hoop het!","Espero que sim!")],
    "Em português usamos o conjuntivo («espero que venhas»); em neerlandês usa-se o presente normal, mas com o verbo no fim.")],
  review=["v-willen","v-graag","v-buitenland","v-ooit","v-later"],
  cefr=C, exs=[
    MA([("hopen","esperar"),("droom","sonho"),("later","no futuro"),("ooit","um dia")], "Desejos.", ["v-hopen","v-droom","v-later","v-ooit-fut"]),
    WO("Espero que venhas.", ["Ik","hoop","dat","je","komt"], "Verbo no fim depois de dat.", ["v-hopen"]),
    FE(["Ik","hoop","dat","jij","morgen","komen."], 5, "komt", "O verbo conjuga-se com o sujeito: dat jij morgen komt.", ["v-hopen"]),
    TR("pt-nl","O meu sonho é viver em Amesterdão.", ["Mijn droom is (om) in Amsterdam te wonen"], "om … te + infinitivo.", ["v-droom"]),
    TR("nl-pt","Later wil ik in het buitenland wonen.", ["No futuro quero viver no estrangeiro","Mais tarde quero viver no estrangeiro","Mais tarde quero morar no estrangeiro"], "later.", ["v-later"]),
    AR("droom","o sonho","de", "De droom.", ["v-droom"]),
    MC("Responder «Espero que sim!»:", ["*Ik hoop het!","Ik hoop ja!|Não se diz assim.","Ik hoop dat!|Falta a oração."], "Ik hoop het.", ["v-hopen"]),
    LI("Ik hoop dat je snel beter wordt.", ["Ik hoop dat je snel beter wordt","Ik hoop dat jij snel beter wordt"], "Espero que melhores depressa.", "Verbo no fim.", ["v-hopen"]),
    FB("Ik wil ___ een eigen huis kopen.", ["later","ooit"], "Futuro distante.", ["v-later","v-ooit-fut"], choices=["later","gisteren","vroeger"], tr="No futuro quero comprar uma casa minha."),
    SW("Escreva 2–3 frases sobre os seus planos e sonhos (use gaan, willen e hopen dat…).", ["Volgend jaar ga ik verhuizen. Later wil ik een eigen bedrijf. Ik hoop dat mijn Nederlands snel beter wordt."], ["Usou **gaan + infinitivo** no fim", "Usou **willen**", "**hopen dat** com o verbo no fim"], 15, "Planos e desejos.", ["v-hopen","v-droom"]),
  ], diff=3, mins=7)

L(5, "Combinar planos com outras pessoas", "Heb je zin om…? Kun je zaterdag? Zullen we om acht uur afspreken?",
  ["Combinar um encontro: propor, verificar disponibilidade e confirmar"],
  vocab=[V("v-kunnen-dag","kun je (zaterdag)?","podes (sábado)?","expression"), V("v-uitkomen-goed","dat komt goed uit","dá jeito|convém","expression"),
         V("v-schikken","schikken","convir|dar jeito","verb",note="Wanneer schikt het jou?"), V("v-doorgaan","doorgaan","realizar-se|manter-se","verb",note="Het feest gaat door. = A festa mantém-se.")],
  ex=[("Kun je zaterdag?","Podes no sábado?"),("Dat komt goed uit.","Isso dá jeito."),("Wanneer schikt het jou?","Quando é que te convém?"),("Gaat het nog door?","Ainda está de pé?")],
  review=["v-zin-hebben","v-afspreken","v-zullen-we","v-uitkomen"],
  cefr=C, exs=[
    MA([("kun je zaterdag?","podes no sábado?"),("dat komt goed uit","dá jeito"),("schikken","convir"),("doorgaan","realizar-se")], "Combinar.", ["v-kunnen-dag","v-uitkomen-goed","v-schikken","v-doorgaan"]),
    TR("pt-nl","Podes no sábado?", ["Kun je zaterdag","Kan je zaterdag","Kun jij zaterdag"], "Kun je + dia.", ["v-kunnen-dag"]),
    TR("nl-pt","Dat komt goed uit.", ["Isso dá jeito","Dá-me jeito","Isso convém"], "Expressão fixa.", ["v-uitkomen-goed"]),
    TR("pt-nl","Ainda está de pé?", ["Gaat het nog door"], "doorgaan.", ["v-doorgaan"]),
    DL([("Kim","Zullen we zaterdag gaan fietsen?","Vamos andar de bicicleta no sábado?"),("Tiago",""),("Kim","Prima, dan zondag om tien uur.","Ótimo, então domingo às dez.")], ["*Zaterdag kan ik niet, maar zondag komt goed uit.","Ja, zaterdag is prima.|A Kim propõe outro dia logo a seguir — não encaixa.","Ik ben gisteren gaan fietsen.|Passado; não responde."], "Recusar e propor alternativa.", ["v-uitkomen-goed"]),
    MC("«Het feest gaat niet door» significa…", ["*A festa foi cancelada.","A festa continua.|«Doorgaan» com «niet» = não se realiza.","A festa é lá dentro.|Não."], "niet doorgaan = ser cancelado.", ["v-doorgaan"]),
    WO("Combinamos às oito?", ["Zullen","we","om","acht","uur","afspreken?"], "Proposta.", ["v-zullen-we","v-afspreken"]),
    LI("Wanneer schikt het jou?", ["Wanneer schikt het jou","Wanneer schikt het je"], "Quando é que te convém?", "schikken.", ["v-schikken"]),
    CO("dialogue","Afspreken", "Noor: Heb je zin om vrijdag naar de bioscoop te gaan?\nPedro: Vrijdag moet ik werken. Kun je zaterdag?\nNoor: Zaterdagavond komt goed uit. Om half acht bij de ingang?\nPedro: Prima, tot zaterdag!",
       [("Porque não pode o Pedro na sexta?", ["*Tem de trabalhar","Está doente","Vai viajar"]),("A que horas se encontram?", ["*Às sete e meia","Às oito e meia","Às seis e meia"])],
       "half acht = sete e meia.", ["v-kunnen-dag","v-uitkomen-goed"]),
    FB("Het concert gaat morgen gewoon ___.", ["door"], "doorgaan (separável).", ["v-doorgaan"], choices=["door","uit","af"], tr="O concerto realiza-se amanhã como previsto."),
  ], diff=3, mins=7)

W()
